  // A reset is a real event a stateful predictor must see. Without it the
  // model keeps state the DUT has just cleared and diverges permanently —
  // silently, and for the rest of the run.
  always @(negedge rst_n) begin
    $display("TXN ddr_cmd reset t=%0t", $time);
  end

  // Transaction detected when: (ddr_cmd != 4'b0111) && (ddr_cmd != 4'b1111)
  always @(posedge clk) begin
    #SAMPLE_DELAY;                 // sample after non-blocking assignments commit
    if (rst_n && ((ddr_cmd != 4'b0111) && (ddr_cmd != 4'b1111))) begin
        $display("TXN ddr_cmd command t=%0t addr=%0h bank=%0h cmd=%0h", $time, ddr_addr, ddr_bank, ddr_cmd);
    end
  end

endmodule
